import{z as E,x as n,o as t,c as B,q as l,j as A,D as e,d as o,s as i,S as s}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"GARCH","description":"","frontmatter":{"title":"GARCH","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/garch.md","filePath":"quant/garch.md","lastUpdated":1791063341000}'),p={name:"quant/garch.md"};function C(_,a,h,m,R,d){const r=n("Mermaid");return t(),B("div",null,[a[2]||(a[2]=l('<h1 id="garch" tabindex="-1">GARCH <a class="header-anchor" href="#garch" aria-label="Permalink to &quot;GARCH&quot;">​</a></h1><div class="epigraph"><p>用过去残差平方的分布滞后生成条件方差，就能在均值方程仍然很瘦的同时，产生波动聚集与肥尾；把滞后写成一个自回归项，阶数不必开到无穷。</p><footer>—— Engle, Autoregressive Conditional Heteroscedasticity, Econometrica 1982；Bollerslev, Generalized Autoregressive Conditional Heteroskedasticity, Journal of Econometrics 1986</footer></div><p><a href="/quant/realized-kernel">上一课</a>把噪声下的 IV 估计写成收益自协方差的核加权和，带宽随噪声–信号比变化。缺口是没有高频时：日收益线性自相关弱，平方自相关强。Engle 的 ARCH 让条件方差成为过去平方冲击的函数；Bollerslev 的 GARCH 把条件方差自身也放进方程。本课写日频默认的条件方差过程。有 RV 时 HAR 与已实现 GARCH 会改写信息集；无 RV 时 GARCH 仍能从一条收益序列抽出 \\(\\sigma_t\\)。不重写核函数与带宽。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记 \\(r_t=\\mu_t+\\varepsilon_t\\)，\\(\\varepsilon_t=\\sigma_t z_t\\)，\\(z_t\\) 为 i.i.d.、均值 0 方差 1。Engle 的 ARCH\\((q)\\) 为 \\(\\sigma_t^2=\\omega+\\sum_{i=1}^q\\alpha_i\\varepsilon_{t-i}^2\\)。要拟合缓慢衰减的平方 ACF，\\(q\\) 必须很大。Bollerslev 写成 GARCH\\((p,q)\\)，标准 GARCH(1,1) 是</p> \\[\\sigma_t^2=\\omega+\\alpha\\varepsilon_{t-1}^2+\\beta\\sigma_{t-1}^2. \\]<p>\\(\\alpha+\\beta\\) 接近 1 时冲击持续很久，但仍是短记忆（指数衰减）。问题是：在正性、平稳性约束下估计 \\((\\omega,\\alpha,\\beta)\\)，使标准化残差 \\(z_t\\) 接近白噪声，并给出一步条件方差。均值 \\(\\mu_t\\) 通常极瘦（常数或略加 AR(1)）；把可预测性塞进均值，会与方差抢同一块平方结构。</p><p><span class="marginnote">术语翻译：GARCH 在做的事，是给「今天的波动会有多大」一个公式——用昨天市场被惊吓的程度（残差平方 \\(\\alpha\\) 项）加昨天的波动水平（\\(\\beta\\) 项），再加一个长期底仓 \\(\\omega\\)。三个参数分工：\\(\\alpha\\) 管反应快慢，\\(\\beta\\) 管记忆长短，\\(\\omega\\) 定长期水平。</span></p><h3 id="无条件方差与持续性必须分开看" tabindex="-1">无条件方差与持续性必须分开看 <a class="header-anchor" href="#无条件方差与持续性必须分开看" aria-label="Permalink to &quot;无条件方差与持续性必须分开看&quot;">​</a></h3><p>平稳时 \\(E[\\sigma_t^2]=\\omega/(1-\\alpha-\\beta)\\)。\\(\\alpha+\\beta\\) 靠近 1，无条件方差对 \\(\\omega\\) 敏感，有限样本里 \\(\\omega\\) 估不稳，长期预测会漂。RiskMetrics 的 IGARCH 令 \\(\\alpha+\\beta=1\\)、无 \\(\\omega\\)，条件方差是平方收益的指数加权，没有无条件均值，长期预测不收敛——这是工程简化，不是 Engle–Bollerslev 的平稳 GARCH。报告应写清：你要的是有均值回复的 \\(\\sigma_t\\)，还是永不回复的 EWMA。</p><p><span class="marginnote">GARCH 滤出的是关于 \\(t-1\\) 可测的条件方差。某一天已经实现的「今日波动」不是 \\(\\sigma_t\\)，而是 \\(|\\varepsilon_t|\\) 或 RV。用 \\(\\sigma_t\\) 去和当日 RV 比，GARCH 少了当日日内信息；这正是已实现 GARCH 要补的测量方程。</span></p><p><span class="marginnote">数字实例：取 \\(\\omega=0.05\\)、\\(\\alpha=0.08\\)、\\(\\beta=0.90\\)，无条件日方差是 \\(0.05/0.02=2.5\\)，即日波动约 1.58%，年化约 25%。而 \\(\\alpha+\\beta=0.98\\) 意味着冲击衰减一半约需 \\(0.69/\\ln(1/0.98)\\approx 34\\) 个交易日——这就是「冲击持续很久」的具体含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>估计。</strong> 条件高斯极大似然（实际上是准似然）：即使 \\(z_t\\) 不是高斯，在正则条件下 QMLE 仍一致，标准误用 Bollerslev–Wooldridge 三明治。收益肥尾时，直接设 \\(z_t\\) 为 t 分布往往更稳，但自由度会与 \\(\\alpha,\\beta\\) 纠缠。约束 \\(\\omega\\gt 0\\)，\\(\\alpha,\\beta\\ge 0\\)，\\(\\alpha+\\beta\\lt 1\\)（协方差平稳）。估计前应把收益按交易日对齐，分红与拆股已调整；均值用常数即可，除非有明确的日历均值。</p><p><strong>诊断。</strong> 标准化残差的 ACF 应接近零，其平方的 ACF 也应被抽干。若平方仍相关，升阶或检查是否缺非对称（交给 <a href="/quant/egarch-gjr">EGARCH / GJR</a>）。若标准化残差仍极肥尾，GARCH 只解释了部分峰度——条件高斯 GARCH 能产生无条件肥尾，但往往不够，需要 t 创新或跳出 GARCH。</p><p><strong>预测。</strong> 一步 \\(\\sigma_{t+1}^2\\) 由滤波给出；多步向无条件方差均值回复，速率由 \\(\\alpha+\\beta\\) 决定。VaR 还要创新分布的分位，不能只把 \\(\\sigma\\) 乘 1.65。期权与多期密度需要模拟或解析矩，GARCH(1,1) 对长地平线会显得记忆不够，那不是调 \\(\\beta\\) 能完全补的，而是模型类的边界。</p><h3 id="信息集是日收益平方-不是-rv" tabindex="-1">信息集是日收益平方，不是 RV <a class="header-anchor" href="#信息集是日收益平方-不是-rv" aria-label="Permalink to &quot;信息集是日收益平方，不是 RV&quot;">​</a></h3><p>ARCH 项 \\(\\varepsilon_{t-1}^2\\) 是对昨日积分波动的噪声极大的代理。一日只有一个平方，噪声–信号比差，所以 \\(\\alpha\\) 通常远小于 HAR 的日系数。这解释了为何有高频 RV 时，用 RV 替换 \\(\\varepsilon^2\\) 会立刻改善——但那就不再是经典 GARCH，而是已实现测量模型。没有高频时，GARCH 仍合理：对象变成「从日收益能提取的条件方差」，不要假装它等于 IV。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是方差的反馈。大冲击抬高 \\(\\sigma_t\\)，使下一期更容易再出现大冲击，从而平方相关、波动聚集。无条件分布是混合：随机的 \\(\\sigma_t\\) 混合出肥尾，即使 \\(z_t\\) 是高斯。持续性 \\(\\alpha+\\beta\\) 高，是因为波动冲击衰减慢，不是因为收益均值有单位根。把 GARCH 残差再去做 <a href="/quant/unit-root">单位根</a> 检验没有对象——\\(r_t\\) 已是 I(0) 附近，\\(\\sigma_t^2\\) 是正的条件二阶矩过程。</p>',20)),(t(),A(s,null,{default:e(()=>[i(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%98%A8%E6%97%A5%E5%A4%A7%E5%86%B2%E5%87%BB%3A%20%CE%B5%C2%B2_%7Bt-1%7D%20%E5%A4%A7%22%5D%20--%3E%20V%5B%22%E4%BB%8A%E6%97%A5%20%CF%83%C2%B2_t%20%E8%A2%AB%E6%8A%AC%E9%AB%98%22%5D%0A%20%20V%20--%3E%20N%5B%22%E4%B8%8B%E4%B8%80%E6%9C%9F%E6%9B%B4%E5%AE%B9%E6%98%93%E5%87%BA%E7%8E%B0%E5%A4%A7%E6%B6%A8%E5%A4%A7%E8%B7%8C%22%5D%0A%20%20N%20--%3E%20C%5B%22%E5%B9%B3%E6%96%B9%E8%87%AA%E7%9B%B8%E5%85%B3%3A%20%E6%B3%A2%E5%8A%A8%E8%81%9A%E9%9B%86%E6%88%90%E7%B0%87%22%5D%0A%20%20V%20--%3E%20F%5B%22%E5%A4%9A%E6%AD%A5%E9%A2%84%E6%B5%8B%E6%B2%BF%20%CE%B1%2B%CE%B2%20%E8%A1%B0%E5%87%8F%22%5D%0A%20%20F%20--%3E%20U%5B%22%E6%94%B6%E6%95%9B%E5%88%B0%E6%97%A0%E6%9D%A1%E4%BB%B6%E6%96%B9%E5%B7%AE%20%CF%89%2F(1-%CE%B1-%CE%B2)%22%5D%0A%20%20P%5B%22%CE%B1%2B%CE%B2%20%E6%8E%A5%E8%BF%91%201%22%5D%20--%3E%20F%0A%20%20P%20--%3E%20L%5B%22%E8%A1%B0%E5%87%8F%E6%85%A2%3A%20%E4%B8%80%E5%9C%BA%E5%8D%B1%E6%9C%BA%E5%BD%B1%E5%93%8D%E6%95%B0%E6%9C%88%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<p>与 <a href="/quant/arma">ARMA</a> 的对应：对 \\(\\varepsilon_t^2\\) 而言，GARCH(1,1) 像 IARCH 的 ARMA(1,1) 表示（Engle 的 ARCH 是分布滞后，\\(\\sigma^2\\) 的 AR 项压缩滞后）。识别上仍应简约：GARCH(1,1) 对多数日收益够用；GARCH(2,2) 常常是在拟合一两次危机，样本外并不更好。</p><p><span class="marginnote">常见误区：初学者容易以为 GARCH 能预测「明天涨还是跌」——它只预测「明天大概率有多颠」。均值方程几乎是平的，GARCH 完全不告诉你方向。波动可预测不等于收益可预测，这也是它在风控里有用、在择时里没用的原因。</span></p><p><span class="marginnote">\\(\\alpha\\) 是「昨日惊吓有多快进入方差」，\\(\\beta\\) 是「旧方差有多黏」。\\(\\alpha\\) 过小、\\(\\beta\\) 过大，滤波几乎是慢 EWMA，对跳反应迟钝；\\(\\alpha\\) 过大则 \\(\\sigma_t\\) 跟着每日平方乱跳，失去「条件」的平滑。两者的权衡是对象，不是越大越好。</span></p><h3 id="与随机波动的差别先写在信息集上" tabindex="-1">与随机波动的差别先写在信息集上 <a class="header-anchor" href="#与随机波动的差别先写在信息集上" aria-label="Permalink to &quot;与随机波动的差别先写在信息集上&quot;">​</a></h3><p>GARCH 的 \\(\\sigma_t\\) 关于过去收益可测，一步预测没有额外冲击。随机波动让方差有自己的新息，滤波是潜变量推断。对日收益拟合，两者都能做聚集与肥尾；对期权，Heston 一类 SV 更常给出闭式或半闭式。先把 GARCH 当作可观测条件方差的工作马，SV 当作多一层冲击的潜波动，已实现测量当作对 IV 的直接观测。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>GARCH(1,1) 对称，不能产生「跌时波动升得更快」的杠杆效应，这是下一篇 EGARCH/GJR 的入口。结构突变会使全样本 \\(\\alpha+\\beta\\) 被高估（Lamoureux–Lastrapes）：危机像永久提高了方差水平，持续性被污染。滚动或允许水平切换会降低 \\(\\alpha+\\beta\\)。日内季节性、隔夜跳不应塞进单方程日 GARCH；隔夜可单独一项。</p><p>工程上：组合风险不要对每只股票估一套不稳定的 GARCH 再加总相关，宁可对因子组合或指数估，个股用 beta 映射。数值上，对 \\(\\omega,\\alpha,\\beta\\) 做对数再参数化以免踩边界；初值用无条件方差与 \\(\\alpha+\\beta=0.95\\) 一类默认。不要用日 GARCH 去描述 tick 波动——对象错了，应回到 RV 与核。不要把 GARCH \\(\\sigma_t\\) 年化后直接当隐含波动卖出信号，中间隔着风险溢价与模型误设。</p><p><span class="marginnote">准似然在厚尾下仍可一致，但小样本里一次暴跌能把 \\(\\beta\\) 推到边界。估计应报告是否顶在 \\(\\alpha+\\beta=1\\)，顶住时长期预测已经坏了，应改 IGARCH、t 创新，或把该日当跳跃单独处理。</span></p>',9)),(t(),A(s,null,{default:e(()=>[i(r,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%97%A5%E6%94%B6%E7%9B%8A%20r_t%22%5D%20--%3E%20M%5B%22%E7%98%A6%E5%9D%87%E5%80%BC%20%CE%BC%22%5D%0A%20%20M%20--%3E%20E%5B%22%E6%AE%8B%E5%B7%AE%20%CE%B5_t%22%5D%0A%20%20E%20--%3E%20A%5B%22ARCH%3A%20%CE%B1%20%CE%B5%C2%B2_%7Bt-1%7D%22%5D%0A%20%20S%5B%22%CF%83%C2%B2_%7Bt-1%7D%22%5D%20--%3E%20B%5B%22GARCH%3A%20%CE%B2%20%CF%83%C2%B2_%7Bt-1%7D%22%5D%0A%20%20A%20--%3E%20V%5B%22%CF%83%C2%B2_t%22%5D%0A%20%20B%20--%3E%20V%0A%20%20V%20--%3E%20Z%5B%22z_t%20%3D%20%CE%B5_t%20%2F%20%CF%83_t%22%5D%0A%20%20Z%20--%3E%20D%5B%22%E8%AF%8A%E6%96%AD%3A%20%E5%B9%B3%E6%96%B9%20ACF%20%E6%98%AF%E5%90%A6%E6%8A%BD%E5%B9%B2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Engle 的 ARCH 用过去平方冲击驱动条件方差；Bollerslev 的 GARCH 加入方差自回归，GARCH(1,1) 是日频默认。</li><li>平稳性要求 \\(\\alpha+\\beta\\lt 1\\)；该和接近 1 时长期预测对 \\(\\omega\\) 敏感，有限样本易漂。</li><li>信息集是日收益平方，噪声大；有 RV 时应换测量，而不是把 GARCH 阶数开大。</li><li>条件高斯即可产生无条件肥尾，但往往不够，需 t 创新或非对称扩展。</li><li>结构突变会抬高表面持续性；对称 GARCH 不解释杠杆效应。</li><li>出处：Engle, <em>Autoregressive Conditional Heteroscedasticity…</em>, Econometrica, 1982；Bollerslev, <em>Generalized Autoregressive Conditional Heteroskedasticity</em>, Journal of Econometrics, 1986。</li></ul>',2))])}const H=E(p,[["render",C]]);export{c as __pageData,H as default};
